/**
 * Username and password auth configuration.
 *
 * @example
 * ```ts
 * import { app } from "@wasp.sh/spec"
 * import { userSignupFields } from "./src/auth" with { type: "ref" }
 *
 * export default app({
 *   // ...
 *   auth: {
 *     userEntity: "User",
 *     methods: {
 *       usernameAndPassword: {
 *         userSignupFields,
 *       },
 *     },
 *     onAuthFailedRedirectTo: "/login",
 *   },
 * })
 * ```
