datasource db {
  provider = "postgresql"
  url      = env("DATABASE_URL")
}

generator client {
  provider = "prisma-client-js"
}

model Product {
  id         Int         @id @default(autoincrement())
  name       String
  price      Float
  inventory  Int
  orderItems OrderItem[]
}

model Coupon {
  id    Int    @id @default(autoincrement())
  code  String @unique
  type  String // "PERCENTAGE" or "FLAT"
  value Float
}

model Order {
  id         Int         @id @default(autoincrement())
  createdAt  DateTime    @default(now())
  subtotal   Float
  discount   Float
  total      Float
  couponCode String?
  items      OrderItem[]
}

model OrderItem {
  id        Int     @id @default(autoincrement())
  orderId   Int
  order     Order   @relation(fields: [orderId], references: [id])
  productId Int
  product   Product @relation(fields: [productId], references: [id])
  quantity  Int
  price     Float
}

import type { PrismaClient } from "@prisma/client";

export async function devSeed(prisma: PrismaClient) {
  await prisma.product.upsert({
    where: { id: 1 },
    update: {
      name: "Premium Wireless Headphones",
      price: 100.00,
      inventory: 10,
    },
    create: {
      id: 1,
      name: "Premium Wireless Headphones",
      price: 100.00,
      inventory: 10,
    },
  });

  await prisma.product.upsert({
    where: { id: 2 },
    update: {
      name: "Ergonomic Mechanical Keyboard",
      price: 150.00,
      inventory: 1,
    },
    create: {
      id: 2,
      name: "Ergonomic Mechanical Keyboard",
      price: 150.00,
      inventory: 1,
    },
  });

  await prisma.coupon.upsert({
    where: { code: "SAVE20" },
    update: {
      type: "PERCENTAGE",
      value: 20.0,
    },
    create: {
      code: "SAVE20",
      type: "PERCENTAGE",
      value: 20.0,
    },
  });

  await prisma.coupon.upsert({
    where: { code: "FLAT50" },
    update: {
      type: "FLAT",
      value: 50.0,
    },
    create: {
      code: "FLAT50",
      type: "FLAT",
      value: 50.0,
    },
  });

  console.log("Database seeded successfully!");
}

import { app, page, route, query, action } from "@wasp.sh/spec";
import { MainPage } from "./src/MainPage" with { type: "ref" };
import { getProducts, getCoupon } from "./src/queries" with { type: "ref" };
import { applyCoupon, checkout } from "./src/actions" with { type: "ref" };
import { devSeed } from "./src/dbSeeds" with { type: "ref" };

export default app({
  name: "app",
  title: "E-commerce Checkout",
  wasp: { version: "^0.24.0" },
  head: ["<link rel='icon' href='/favicon.ico' />"],
  db: {
    seeds: [devSeed],
  },
  spec: [
    route("RootRoute", "/", page(MainPage)),
    query(getProducts, { entities: ["Product"] }),
    query(getCoupon, { entities: ["Coupon"] }),
    action(applyCoupon, { entities: ["Coupon"] }),
    action(checkout, { entities: ["Product", "Coupon", "Order", "OrderItem"] }),
  ],
});

import { HttpError } from "wasp/server";

export const getProducts = async (args: any, context: any) => {
  return context.entities.Product.findMany({
    orderBy: { id: "asc" },
  });
};

export const getCoupon = async (args: { code: string }, context: any) => {
  if (!args.code) {
    throw new HttpError(400, "Coupon code is required");
  }
  const coupon = await context.entities.Coupon.findUnique({
    where: { code: args.code.toUpperCase() },
  });
  if (!coupon) {
    throw new HttpError(404, "Invalid coupon code");
  }
  return coupon;
};

import { HttpError } from "wasp/server";

export const applyCoupon = async (args: { code: string }, context: any) => {
  if (!args.code) {
    throw new HttpError(400, "Coupon code is required");
  }
  const coupon = await context.entities.Coupon.findUnique({
    where: { code: args.code.toUpperCase() },
  });
  if (!coupon) {
    throw new HttpError(404, "Invalid coupon code");
  }
  return coupon;
};

export const checkout = async (
  args: { items: { productId: number; quantity: number }[]; couponCode?: string },
  context: any
) => {
  const { items, couponCode } = args;

  if (!items || items.length === 0) {
    throw new HttpError(400, "Cart is empty");
  }

  // Use interactive transaction to guarantee atomicity and locking
  const order = await context.prisma.$transaction(async (tx: any) => {
    let subtotal = 0;
    const orderItemsToCreate = [];

    // Loop through each item and lock/update product inventory
    for (const item of items) {
      if (item.quantity <= 0) {
        throw new HttpError(400, `Invalid quantity for product ID: ${item.productId}`);
      }

      // Lock the product row using SELECT ... FOR UPDATE
      const products = await tx.$queryRaw`
        SELECT id, name, price, inventory FROM "Product"
        WHERE id = ${item.productId}
        FOR UPDATE
      `;

      if (!products || products.length === 0) {
        throw new HttpError(404, `Product not found: ID ${item.productId}`);
      }

      const product = products[0];

      if (product.inventory < item.quantity) {
        throw new HttpError(400, "Insufficient inventory");
      }

      // Decrement the inventory
      await tx.product.update({
        where: { id: item.productId },
        data: {
          inventory: {
            decrement: item.quantity,
          },
        },
      });

      const itemPrice = product.price;
      subtotal += itemPrice * item.quantity;

      orderItemsToCreate.push({
        productId: item.productId,
        quantity: item.quantity,
        price: itemPrice,
      });
    }

    // Apply coupon if provided
    let discount = 0;
    if (couponCode) {
      const coupon = await tx.coupon.findUnique({
        where: { code: couponCode.toUpperCase() },
      });
      if (!coupon) {
        throw new HttpError(400, "Invalid coupon code");
      }

      if (coupon.type === "PERCENTAGE") {
        discount = subtotal * (coupon.value / 100);
      } else if (coupon.type === "FLAT") {
        discount = coupon.value;
      }

      if (discount > subtotal) {
        discount = subtotal;
      }
    }

    const total = subtotal - discount;

    // Create the order
    const newOrder = await tx.order.create({
      data: {
        subtotal,
        discount,
        total,
        couponCode: couponCode ? couponCode.toUpperCase() : null,
        items: {
          create: orderItemsToCreate.map((item) => ({
            productId: item.productId,
            quantity: item.quantity,
            price: item.price,
          })),
        },
      },
    });

    return newOrder;
  });

  return order;
};

import { useQuery, getProducts } from "wasp/client/operations";
import { applyCoupon, checkout } from "wasp/client/operations";
import { useState } from "react";
import "./Main.css";

interface Product {
  id: number;
  name: string;
  price: number;
  inventory: number;
}

interface Coupon {
  id: number;
  code: string;
  type: "PERCENTAGE" | "FLAT";
  value: number;
}

export function MainPage() {
  const { data: products, isLoading, error: productsError } = useQuery(getProducts);

  // Cart state: map of productId -> quantity
  const [cart, setCart] = useState<Record<number, number>>({});
  const [couponCode, setCouponCode] = useState("");
  const [appliedCoupon, setAppliedCoupon] = useState<Coupon | null>(null);

  const [couponMessage, setCouponMessage] = useState<{ text: string; isError: boolean } | null>(null);
  const [checkoutMessage, setCheckoutMessage] = useState<{ text: string; isError: boolean } | null>(null);
  const [isSubmitting, setIsSubmitting] = useState(false);

  const handleAddToCart = (product: Product) => {
    setCart((prev) => {
      const currentQty = prev[product.id] || 0;
      return {
        ...prev,
        [product.id]: currentQty + 1,
      };
    });
  };

  const handleRemoveFromCart = (productId: number) => {
    setCart((prev) => {
      const newCart = { ...prev };
      delete newCart[productId];
      return newCart;
    });
  };

  const updateQuantity = (productId: number, qty: number) => {
    if (qty <= 0) {
      handleRemoveFromCart(productId);
      return;
    }
    setCart((prev) => ({
      ...prev,
      [productId]: qty,
    }));
  };

  const handleApplyCoupon = async (e: React.FormEvent) => {
    e.preventDefault();
    setCouponMessage(null);

    if (!couponCode.trim()) {
      setCouponMessage({ text: "Please enter a coupon code", isError: true });
      return;
    }

    try {
      const coupon = await applyCoupon({ code: couponCode.trim() });
      setAppliedCoupon(coupon);
      setCouponMessage({ text: "Coupon applied successfully!", isError: false });
    } catch (err: any) {
      setAppliedCoupon(null);
      const errMsg = err.message || "Invalid coupon code";
      setCouponMessage({ text: errMsg, isError: true });
    }
  };

  const handleCheckout = async () => {
    setCheckoutMessage(null);
    setIsSubmitting(true);

    const cartItems = Object.entries(cart)
      .filter(([_, qty]) => qty > 0)
      .map(([id, qty]) => ({
        productId: parseInt(id, 10),
        quantity: qty,
      }));

    if (cartItems.length === 0) {
      setCheckoutMessage({ text: "Your cart is empty.", isError: true });
      setIsSubmitting(false);
      return;
    }

    try {
      const order = await checkout({
        items: cartItems,
        couponCode: appliedCoupon?.code,
      });

      setCheckoutMessage({
        text: `Order placed successfully! Order ID: ${order.id}`,
        isError: false,
      });
      // Clear cart and coupon state on success
      setCart({});
      setCouponCode("");
      setAppliedCoupon(null);
      setCouponMessage(null);
    } catch (err: any) {
      const errMsg = err.message || "Checkout failed";
      // Ensure we display "Insufficient inventory" or "Out of stock" clearly on inventory failure
      setCheckoutMessage({ text: errMsg, isError: true });
    } finally {
      setIsSubmitting(false);
    }
  };

  // Calculations
  const cartItemsList = products
    ? Object.entries(cart)
        .map(([id, qty]) => {
          const product = products.find((p: Product) => p.id === parseInt(id, 10));
          return product ? { product, quantity: qty } : null;
        })
        .filter((item): item is { product: Product; quantity: number } => item !== null)
    : [];

  const subtotal = cartItemsList.reduce((acc, item) => acc + item.product.price * item.quantity, 0);

  let discount = 0;
  if (appliedCoupon) {
    if (appliedCoupon.type === "PERCENTAGE") {
      discount = subtotal * (appliedCoupon.value / 100);
    } else if (appliedCoupon.type === "FLAT") {
      discount = appliedCoupon.value;
    }
    if (discount > subtotal) {
      discount = subtotal;
    }
  }

  const total = subtotal - discount;

  return (
    <div className="ecommerce-container">
      <header className="header">
        <h1>Wasp E-Commerce Checkout</h1>
      </header>

      {productsError && (
        <div className="error-banner">
          Error loading products: {productsError.message || "Unknown error"}
        </div>
      )}

      {isLoading ? (
        <div className="loading">Loading products...</div>
      ) : (
        <div className="main-layout">
          {/* Product Catalog Section */}
          <section className="catalog-section">
            <h2>Product Catalog</h2>
            <div className="products-grid">
              {products?.map((product: Product) => (
                <div key={product.id} className="product-card">
                  <div className="product-info">
                    <h3>{product.name}</h3>
                    <p className="product-price">${product.price.toFixed(2)}</p>
                    <p className="product-inventory">
                      Available Inventory: <strong>{product.inventory}</strong>
                    </p>
                  </div>
                  <button
                    className="add-to-cart-btn"
                    onClick={() => handleAddToCart(product)}
                    disabled={product.inventory <= 0}
                  >
                    {product.inventory <= 0 ? "Out of Stock" : "Add to Cart"}
                  </button>
                </div>
              ))}
            </div>
          </section>

          {/* Shopping Cart Section */}
          <section className="cart-section">
            <h2>Your Shopping Cart</h2>
            {cartItemsList.length === 0 ? (
              <p className="empty-cart-text">Your cart is empty. Add some products!</p>
            ) : (
              <div className="cart-container">
                <div className="cart-items-list">
                  {cartItemsList.map((item) => (
                    <div key={item.product.id} className="cart-item">
                      <div className="cart-item-details">
                        <h4>{item.product.name}</h4>
                        <p>${item.product.price.toFixed(2)} each</p>
                      </div>
                      <div className="cart-item-actions">
                        <div className="quantity-controls">
                          <button
                            onClick={() => updateQuantity(item.product.id, item.quantity - 1)}
                          >
                            -
                          </button>
                          <span>{item.quantity}</span>
                          <button
                            onClick={() => updateQuantity(item.product.id, item.quantity + 1)}
                          >
                            +
                          </button>
                        </div>
                        <button
                          className="remove-item-btn"
                          onClick={() => handleRemoveFromCart(item.product.id)}
                        >
                          Remove
                        </button>
                      </div>
                    </div>
                  ))}
                </div>

                {/* Coupon Application */}
                <form onSubmit={handleApplyCoupon} className="coupon-form">
                  <input
                    type="text"
                    id="coupon-input"
                    placeholder="Enter Coupon Code"
                    value={couponCode}
                    onChange={(e) => setCouponCode(e.target.value)}
                  />
                  <button type="submit" id="apply-coupon-btn">
                    Apply Coupon
                  </button>
                </form>

                {couponMessage && (
                  <p className={`message ${couponMessage.isError ? "error" : "success"}`}>
                    {couponMessage.text}
                  </p>
                )}

                {/* Pricing Summary */}
                <div className="pricing-summary">
                  <div className="summary-row">
                    <span>Subtotal:</span>
                    <span>${subtotal.toFixed(2)}</span>
                  </div>
                  {discount > 0 && (
                    <div className="summary-row discount">
                      <span>Discount ({appliedCoupon?.code}):</span>
                      <span>-${discount.toFixed(2)}</span>
                    </div>
                  )}
                  <div className="summary-row total">
                    <span>Grand Total:</span>
                    <span>${total.toFixed(2)}</span>
                  </div>
                </div>

                {/* Checkout Action */}
                <button
                  id="checkout-btn"
                  className="checkout-btn"
                  onClick={handleCheckout}
                  disabled={isSubmitting}
                >
                  {isSubmitting ? "Processing..." : "Place Order"}
                </button>

                {checkoutMessage && (
                  <div
                    className={`checkout-status-message ${
                      checkoutMessage.isError ? "error" : "success"
                    }`}
                  >
                    {checkoutMessage.text}
                  </div>
                )}
              </div>
            )}
          </section>
        </div>
      )}
    </div>
  );
}

